import * as THREE from 'three/webgpu';
import { MeshPhysicalNodeMaterial, color } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-features-thumb-card';
  group.position.set(-1.25, -1.1, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // caption strip (machined metal panel) beneath the mesh
  const stripGeo = new THREE.BoxGeometry(1.6, 0.32, 0.02);
  const stripMat = new MeshPhysicalNodeMaterial();
  stripMat.colorNode = color(colors.ink);
  stripMat.metalness = 0.5;
  stripMat.roughness = 0.55;
  stripMat.clearcoat = 0.2;
  const strip = new THREE.Mesh(stripGeo, stripMat);
  strip.position.set(0, -0.9, 0);
  group.add(strip);

  // accent rim light strip edge
  const rimGeo = new THREE.BoxGeometry(1.6, 0.02, 0.02);
  const rimMat = new MeshPhysicalNodeMaterial();
  rimMat.colorNode = color(colors.accent);
  rimMat.metalness = 0.4;
  rimMat.roughness = 0.4;
  rimMat.emissiveNode = color(colors.accent);
  const rim = new THREE.Mesh(rimGeo, rimMat);
  rim.position.set(0, -0.74, 0.01);
  group.add(rim);

  let meshObj = null;
  const meshUrl = '/prism-mock/orrery/meshes/gear-a.glb';

  try {
    const gltf = ctx.glbLoader.load(meshUrl);
    if (gltf) {
      meshObj = gltf.scene ? gltf.scene : gltf;
      meshObj.position.set(0, 0.15, 0);
      meshObj.scale.set(0.9, 0.9, 0.9);
      group.add(meshObj);
    }
  } catch (e) {
    // mesh load failure - continue with card shell only
  }

  const baseY = group.position.y;
  let hovered = false;

  ctx.primitives['parallax-scroll'](group, { intensity: 0.4 });
  ctx.primitives['magnetic-cursor'](group, { radius: 1.2, strength: 0.35 });

  let riseTween = null;

  const onPointerOver = () => {
    if (hovered) return;
    hovered = true;
    if (riseTween) riseTween.kill();
    riseTween = gsap.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  const onPointerOut = () => {
    hovered = false;
    if (riseTween) riseTween.kill();
    riseTween = gsap.to(group.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  const onClick = () => {
    gsap.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
      yoyo: true,
      repeat: 1,
      onComplete: () => {
        if (group.userData.emit) {
          group.userData.emit('hub-features.select');
        }
      }
    });
  };

  // weighted-settle entrance
  group.scale.set(0.001, 0.001, 0.001);
  const settleTween = gsap.timeline();
  settleTween.to(group.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.6,
    ease: 'power4.out'
  }).to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.3,
    ease: 'power4.out'
  });

  group.userData.handlers = {
    pointerover: onPointerOver,
    pointerout: onPointerOut,
    click: onClick
  };

  group.userData.cleanup = () => {
    if (riseTween) riseTween.kill();
    settleTween.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);

    stripGeo.dispose();
    stripMat.dispose();
    rimGeo.dispose();
    rimMat.dispose();

    if (meshObj) {
      meshObj.traverse((child) => {
        if (child.isMesh) {
          if (child.geometry) child.geometry.dispose();
          if (child.material) {
            if (Array.isArray(child.material)) {
              child.material.forEach((m) => m.dispose());
            } else {
              child.material.dispose();
            }
          }
        }
      });
    }
  };

  return group;
}
